SELECT COUNT(*) AS pending_reservation_count
FROM agent_v3_reservation_view
WHERE agent_v3_reservation_view.store_id = ANY(:allowedStoreIds) AND agent_v3_reservation_view.date >= :startAt AND agent_v3_reservation_view.date < :endAt AND (status = '***') LIMIT 100;

SELECT SUM(current_stock) AS inventory_on_hand
FROM agent_v3_product_inventory_view
WHERE agent_v3_product_inventory_view.store_id = ANY(:allowedStoreIds) AND (product_name = '***') LIMIT 100;

SELECT p.product_name, p.sku, p.unit, p.current_stock, p.safety_stock, p.status
FROM agent_v3_product_inventory_view AS p WHERE p.store_id = ANY(:allowedStoreIds) ORDER BY p.current_stock ASC
LIMIT 20;
